/* GERADO por scripts/dividir-dados.js — não edite à mão.
   A fonte editável continua sendo js/data*.js. */
registrarDetalhes({"CT-001":{"cognitivo":{"motivo":"Base de toda a contabilidade — item 2 do edital.","palavraCritica":"A = P + PL ⇔ PL = A − P"},"comentario":{"resolucao":"CERTO. Equação fundamental: ATIVO = PASSIVO + PATRIMÔNIO LÍQUIDO. Daí a situação líquida (PL) = Ativo − Passivo exigível. PL positivo: ativo supera obrigações; PL negativo (passivo a descoberto): dívidas superam bens e direitos.","fundamento":"Teoria contábil — estática patrimonial.","macete":"Balanço 'fecha' sempre: os dois lados pesam igual por definição.","erroComum":"Inverter os termos da diferença na situação líquida.","comoBancaPensa":"Fórmula de três termos = três pontos de troca possíveis; conferir cada termo é obrigatório."}},"CT-002":{"cognitivo":{"motivo":"Classificação dos fatos contábeis — item 3 do edital.","palavraCritica":"não altera o PL"},"comentario":{"resolucao":"ERRADO. Trata-se de fato PERMUTATIVO (ou qualitativo): troca de um ativo (caixa) por outro (veículo) de igual valor, alterando a composição do patrimônio sem modificar o total do PL. Modificativos envolvem receitas ou despesas (ex.: pagamento de salários); mistos combinam permuta e modificação (ex.: venda de mercadoria com lucro).","fundamento":"Teoria contábil — classificação dos fatos administrativos.","macete":"Se não passou por receita/despesa, o PL nem percebeu.","erroComum":"Confundir saída de caixa com redução de riqueza própria.","comoBancaPensa":"Classificação tripartite = rotação constante de exemplos com rótulo trocado."}},"CT-003":{"cognitivo":{"motivo":"Desfazer a associação leiga débito=ruim / crédito=bom.","palavraCritica":"natureza da conta"},"comentario":{"resolucao":"ERRADO. O efeito do débito e do crédito depende da natureza da conta: nas contas de natureza devedora (ativo e despesas), o débito aumenta e o crédito diminui o saldo; nas de natureza credora (passivo, patrimônio líquido e receitas), ocorre o inverso. Não há 'sempre'.","fundamento":"Método das partidas dobradas — natureza e funcionamento das contas.","macete":"Comprar caixa (ativo) se faz DEBITANDO caixa — débito aumentando saldo.","erroComum":"Importar a semântica do extrato bancário para a escrituração.","comoBancaPensa":"'Sempre' + regra que comporta duas famílias de contas = item errado sob medida."}},"CT-004":{"cognitivo":{"motivo":"Limite técnico do balancete — pega quem o toma por auditoria.","palavraCritica":"necessária ≠ suficiente"},"comentario":{"resolucao":"ERRADO. A igualdade débitos = créditos é consequência automática das partidas dobradas e revela apenas equilíbrio aritmético. Persistem invisíveis ao balancete: omissão integral de lançamento, duplicidade, inversão de contas, classificação incorreta e erros de igual valor em ambos os lados.","fundamento":"Técnica contábil — balancete de verificação (limitações).","macete":"Fechar as somas ≠ contar a verdade: fraude bem lançada também 'bate'.","erroComum":"Tratar o balancete como prova de exatidão da escrituração.","comoBancaPensa":"Para carreira policial, o detalhe é investigativo: livros equilibrados podem esconder fraude."}},"CT-005":{"cognitivo":{"motivo":"Tipologia expressamente citada no edital (item 9 de Análise Financeira).","palavraCritica":"abaixo do limiar de comunicação"},"comentario":{"resolucao":"CERTO. Smurfing (ou structuring) é o fracionamento deliberado de valores em operações menores, distribuídas em datas, contas ou agências distintas, para escapar dos limiares de comunicação automática ao COAF (Lei 9.613/1998; Circular Bacen 3.978/2020). Integra a fase de colocação da lavagem.","fundamento":"Lei 9.613/1998; tipologias GAFI/COAF.","macete":"Depósitos 'redondos', repetidos e logo abaixo do limite = alerta máximo.","erroComum":"Confundir com a mera utilização de interpostas pessoas (laranjas).","comoBancaPensa":"Termo técnico do edital novo = definição literal cobrada nas primeiras provas."}},"CT-006":{"cognitivo":{"motivo":"Red flags dos itens 7-13 do edital + valor probatório do indício.","palavraCritica":"orientar a investigação"},"comentario":{"resolucao":"CERTO. Movimentações incompatíveis com a renda e a interposição de terceiros são tipologias clássicas de ocultação patrimonial (Lei 9.613/1998) e fundamentam relatórios de inteligência financeira e medidas investigativas. Contudo, a condenação exige o standard probatório do processo penal — indícios isolados não bastam.","fundamento":"Lei 9.613/1998; tipologias COAF/GAFI; CPP, art. 239 (conceito de indício).","macete":"Vida de rico com renda de pobre: o papel do investigador é seguir o dinheiro (follow the money).","erroComum":"Tratar red flags como prova cabal — ou, no extremo oposto, como irrelevantes.","comoBancaPensa":"Item longo e tecnicamente equilibrado — treina a imunidade ao 'item extenso parece errado'."}},"CT-007":{"cognitivo":{"motivo":"Distinguir fatos permutativos, modificativos e mistos.","palavraCritica":"permutativo NÃO altera PL; modificativo altera"},"comentario":{"resolucao":"ERRADO. As definições estão trocadas. O fato PERMUTATIVO apenas permuta elementos patrimoniais SEM alterar o patrimônio líquido (ex.: compra de bem à vista). O fato MODIFICATIVO altera a situação líquida (ex.: pagamento de despesa, recebimento de receita). O misto combina os dois efeitos.","fundamento":"Contabilidade geral — fatos contábeis.","macete":"Permutativo = permuta (PL não muda). Modificativo = modifica o PL.","erroComum":"Inverter qual fato altera o patrimônio líquido.","comoBancaPensa":"Par conceitual espelhado (permutativo × modificativo) invertido."}},"CT-008":{"cognitivo":{"motivo":"Cobrar a estrutura do balanço e a equação patrimonial.","palavraCritica":"PL = Ativo − Passivo"},"comentario":{"resolucao":"CERTO. O balanço patrimonial reflete a equação fundamental: Ativo = Passivo + Patrimônio Líquido. O ativo (bens e direitos) fica à esquerda; o passivo (obrigações) e o PL (situação líquida = A − P) à direita. O PL é a riqueza própria da entidade.","fundamento":"Contabilidade geral — balanço patrimonial e equação patrimonial.","macete":"A = P + PL. Se A > P, situação líquida positiva (PL positivo).","erroComum":"Trocar a natureza de passivo (obrigação) por bens/direitos.","comoBancaPensa":"A composição do balanço é cobrada invertendo o que é ativo/passivo/PL."}},"CT-009":{"cognitivo":{"motivo":"Distinguir a DRE (dinâmica, resultado) do balanço (estático, posição).","palavraCritica":"posição estática = balanço (não DRE)"},"comentario":{"resolucao":"ERRADO. A descrição corresponde ao BALANÇO PATRIMONIAL (posição estática numa data). A DRE é dinâmica: confronta receitas e despesas do período para apurar o resultado (lucro ou prejuízo) do exercício.","fundamento":"Contabilidade geral — DRE × balanço patrimonial.","macete":"DRE = resultado do período (filme). Balanço = posição na data (foto).","erroComum":"Trocar a função da DRE pela do balanço.","comoBancaPensa":"Par espelhado (DRE × balanço) invertido na assertiva."}},"CT-010":{"cognitivo":{"motivo":"Distinguir contas patrimoniais das contas de resultado.","palavraCritica":"receita e despesa = contas de resultado"},"comentario":{"resolucao":"ERRADO. Receitas e despesas são contas de RESULTADO, que compõem a DRE e, após a apuração, transferem o resultado ao patrimônio líquido. As contas patrimoniais são as de ativo, passivo e PL, que integram o balanço.","fundamento":"Contabilidade geral — plano de contas.","macete":"Receita/despesa = resultado (DRE). Ativo/passivo/PL = patrimonial (balanço).","erroComum":"Classificar receita e despesa como patrimoniais.","comoBancaPensa":"Classificação de contas é cobrada trocando patrimonial × resultado."}},"CT-011":{"cognitivo":{"motivo":"Cobrar o cálculo e a interpretação da liquidez corrente.","palavraCritica":"AC ÷ PC > 1 = boa liquidez de curto prazo"},"comentario":{"resolucao":"CERTO. Liquidez Corrente = Ativo Circulante ÷ Passivo Circulante. Índice maior que 1 indica que, para cada unidade de obrigação de curto prazo, há mais de uma unidade de recursos de curto prazo — capacidade de honrar dívidas de curto prazo.","fundamento":"Análise das demonstrações contábeis — índices de liquidez.","macete":"LC = AC/PC. > 1 bom, = 1 no limite, < 1 aperto de caixa.","erroComum":"Inverter a fórmula (PC/AC) ou a leitura do resultado.","comoBancaPensa":"Fórmula de índice financeiro é cobrada invertendo numerador/denominador."}},"CT-012":{"cognitivo":{"motivo":"Cobrar o princípio das partidas dobradas.","palavraCritica":"não há necessariamente (falso)"},"comentario":{"resolucao":"ERRADO. No método das partidas dobradas (Luca Pacioli), para cada débito há sempre um crédito de igual valor — 'não há débito sem crédito correspondente'. Por isso, no balancete, a soma dos débitos é igual à soma dos créditos.","fundamento":"Contabilidade geral — método das partidas dobradas.","macete":"Débito = Crédito, sempre. Se não bate, há erro de escrituração.","erroComum":"Negar a igualdade obrigatória débito/crédito.","comoBancaPensa":"Nega o princípio-base da escrituração contábil."}},"CT-013":{"cognitivo":{"motivo":"Reconhecer tipologias de lavagem listadas nominalmente no edital.","palavraCritica":"fracionamento para evitar detecção"},"comentario":{"resolucao":"CERTO. O fracionamento intencional de valores para permanecer abaixo do limite de comunicação obrigatória é a tipologia denominada SMURFING (ou structuring). O uso de contas de pessoas sem lastro econômico caracteriza a utilização de “laranjas” (interpostas pessoas) — ambas expressamente listadas no programa do certame.","fundamento":"Lei 9.613/1998; normas do COAF; tipologias de lavagem.","macete":"Vários depósitos 'quase no limite' = smurfing. Conta de terceiro sem renda = laranja.","erroComum":"Não identificar o nome técnico da tipologia.","comoBancaPensa":"Aplica tipologias do edital a um cenário investigativo concreto."}},"CT-014":{"cognitivo":{"motivo":"Cobrar a ordem e o conteúdo das fases da lavagem.","palavraCritica":"integração (deveria ser colocação)"},"comentario":{"resolucao":"ERRADO. Há dois erros. Primeiro, o depósito em espécie corresponde à fase de COLOCAÇÃO (placement), em que os valores ingressam no sistema financeiro. Segundo, a ordem correta das fases é colocação → ocultação (layering) → integração, e não a apresentada.","fundamento":"Doutrina sobre lavagem de dinheiro (modelo trifásico do GAFI); Lei 9.613/1998.","macete":"C-O-I: Coloca, Oculta, Integra. Depósito em espécie está no começo.","erroComum":"Inverter a ordem das fases ou trocar colocação por integração.","comoBancaPensa":"Inverte a sequência de um processo em etapas — pegadinha clássica."}},"CT-015":{"cognitivo":{"motivo":"Cobrar a natureza estática do balanço patrimonial e sua composição básica.","palavraCritica":"em determinada data"},"comentario":{"resolucao":"CERTO. O balanço patrimonial é demonstração contábil estática, que evidencia a posição patrimonial e financeira da entidade em determinada data, estruturada em três grandes grupos: ativo, passivo e patrimônio líquido.","fundamento":"Lei nº 6.404/1976 (Lei das S.A.); doutrina contábil (estrutura das demonstrações financeiras).","macete":"Balanço: retrato de UMA DATA. Ativo = Passivo + PL.","erroComum":"Confundir o balanço (estático) com demonstrações de fluxo, como a DRE.","comoBancaPensa":"Item de fixação sobre a natureza e a estrutura básica do balanço patrimonial."}},"CT-016":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a natureza estática do balanço patrimonial.","palavraCritica":"resultado ... ao longo de um período"},"comentario":{"resolucao":"ERRADO. Quem evidencia o resultado (lucro ou prejuízo) de um período é a Demonstração do Resultado do Exercício (DRE) — o balanço patrimonial, por sua vez, evidencia a posição patrimonial e financeira da entidade em determinada data, e não um fluxo ao longo de um período.","fundamento":"Lei nº 6.404/1976; doutrina contábil (estrutura das demonstrações financeiras).","macete":"Resultado do período = função da DRE, não do balanço.","erroComum":"Atribuir ao balanço patrimonial uma função que é típica da DRE.","comoBancaPensa":"Troca as funções de duas demonstrações contábeis distintas, testando a precisão conceitual."}},"CT-017":{"cognitivo":{"motivo":"Cobrar que a incompatibilidade financeira é indício, não prova conclusiva isolada.","palavraCritica":"apenas indício ... insuficiente, por si só"},"comentario":{"resolucao":"CERTO. A incompatibilidade entre os fluxos financeiros de uma pessoa e sua capacidade econômica declarada é um indício relevante para a investigação, mas não constitui, isoladamente, prova conclusiva de fraude contábil ou de crime contra a ordem tributária — é necessária a análise conjunta de outros elementos probatórios.","fundamento":"Doutrina de análise financeira e contábil aplicada à investigação (indícios de lavagem/fraude).","macete":"Incompatibilidade patrimonial = indício, não prova conclusiva isolada.","erroComum":"Tratar a incompatibilidade patrimonial como prova suficiente, por si só, de ilícito.","comoBancaPensa":"Item de fixação sobre o valor probatório relativo dos indícios financeiros."}},"CT-018":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a incompatibilidade financeira é apenas indício, não prova conclusiva.","palavraCritica":"suficiente, por si só ... dispensando-se"},"comentario":{"resolucao":"ERRADO. A incompatibilidade entre os fluxos financeiros e a capacidade econômica declarada é apenas um indício relevante, mas não é suficiente, por si só, para comprovar fraude contábil ou crime contra a ordem tributária — exige-se sempre a análise conjunta de outros elementos probatórios.","fundamento":"Doutrina de análise financeira e contábil aplicada à investigação.","macete":"Nenhum indício isolado basta sozinho — sempre é necessário o conjunto probatório.","erroComum":"Tratar um único indício, ainda que relevante, como prova conclusiva e autossuficiente.","comoBancaPensa":"Generaliza indevidamente o valor probatório de um indício isolado."}},"CT-019":{"cognitivo":{"motivo":"Cobrar a importância da etapa de identificação na gestão de riscos financeiros.","palavraCritica":"etapa essencial"},"comentario":{"resolucao":"CERTO. A identificação de riscos financeiros é etapa essencial e inicial do processo de gestão de riscos, permitindo à entidade reconhecer eventos internos ou externos capazes de afetar negativamente o alcance de seus objetivos financeiros, antes de avaliá-los e tratá-los.","fundamento":"Doutrina de gestão de riscos financeiros e controles internos.","macete":"Sem identificar o risco, não há como avaliar nem tratar — é a etapa inicial e essencial.","erroComum":"Considerar a identificação como etapa dispensável ou meramente formal.","comoBancaPensa":"Item de fixação sobre o papel central da identificação no ciclo de gestão de riscos."}},"CT-020":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a identificação de riscos é etapa indispensável.","palavraCritica":"dispensa ... bastando"},"comentario":{"resolucao":"ERRADO. A identificação de riscos é etapa essencial e contínua da gestão de riscos financeiros, não podendo ser dispensada — o monitoramento de indicadores já conhecidos não substitui a necessidade de identificar novos riscos e eventos emergentes que possam afetar os objetivos da entidade.","fundamento":"Doutrina de gestão de riscos financeiros e controles internos.","macete":"Identificação de riscos: sempre necessária e contínua, nunca dispensável.","erroComum":"Achar que o monitoramento de indicadores conhecidos substitui a identificação de novos riscos.","comoBancaPensa":"Generaliza indevidamente que uma etapa avançada do processo (monitoramento) dispensa a etapa inicial (identificação)."}},"CT-021":{"cognitivo":{"motivo":"Cobrar a distinção entre a DRE (fluxo de um período) e o balanço patrimonial (posição em uma data).","palavraCritica":"ao longo de um período ... data específica"},"comentario":{"resolucao":"CERTO. A DRE é demonstração de natureza dinâmica, que apura receitas, custos, despesas e o resultado (lucro ou prejuízo) ao longo de um período, diferindo do balanço patrimonial, de natureza estática, que evidencia a posição patrimonial da entidade em uma data específica.","fundamento":"Lei nº 6.404/1976; doutrina contábil (estrutura das demonstrações financeiras).","macete":"DRE = período (fluxo). Balanço = data (posição).","erroComum":"Inverter as naturezas das duas demonstrações contábeis.","comoBancaPensa":"Item de fixação sobre a distinção estrutural entre as duas principais demonstrações contábeis."}},"CT-022":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a DRE apura resultado de um período, e não posição em uma data.","palavraCritica":"data específica ... e não o resultado"},"comentario":{"resolucao":"ERRADO. A DRE é elaborada para apurar o resultado (receitas, custos, despesas e lucro/prejuízo) ao longo de um PERÍODO, e não para retratar a posição patrimonial em uma data específica — essa última função é do balanço patrimonial, e não da DRE.","fundamento":"Lei nº 6.404/1976; doutrina contábil (estrutura das demonstrações financeiras).","macete":"DRE: sempre um período (fluxo), nunca uma data isolada.","erroComum":"Atribuir à DRE a natureza estática que é, na verdade, do balanço patrimonial.","comoBancaPensa":"Troca as naturezas de duas demonstrações contábeis distintas."}},"CT-023":{"cognitivo":{"motivo":"Cobrar a distinção entre análise vertical e análise horizontal de demonstrações contábeis.","palavraCritica":"vertical ... participação percentual. Horizontal ... evolução"},"comentario":{"resolucao":"CERTO. A análise vertical evidencia a participação percentual de cada conta em relação a um valor-base dentro de um mesmo período, enquanto a análise horizontal evidencia a evolução de cada conta ao longo de diferentes períodos, permitindo identificar tendências de crescimento ou retração.","fundamento":"Doutrina contábil — técnicas de análise de demonstrações financeiras (análise vertical e horizontal).","macete":"Vertical = % de participação (mesma data). Horizontal = evolução no tempo.","erroComum":"Inverter as definições de análise vertical e horizontal.","comoBancaPensa":"Item de fixação sobre a distinção clássica entre as duas técnicas de análise."}},"CT-024":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a distinção entre análise vertical e horizontal.","palavraCritica":"horizontal ... participação percentual"},"comentario":{"resolucao":"ERRADO. Os conceitos foram invertidos: é a análise VERTICAL (e não a horizontal) que evidencia a participação percentual de cada conta em relação a um valor-base dentro de um mesmo período; é a análise HORIZONTAL (e não a vertical) que evidencia a evolução das contas ao longo de diferentes períodos.","fundamento":"Doutrina contábil — técnicas de análise de demonstrações financeiras.","macete":"Vertical = % (mesma data). Horizontal = evolução (vários períodos).","erroComum":"Não perceber a inversão proposital entre os dois conceitos.","comoBancaPensa":"Testa a mesma distinção clássica, mas com os termos deliberadamente trocados."}},"CT-025":{"cognitivo":{"motivo":"Cobrar a fórmula e a interpretação do índice de liquidez corrente.","palavraCritica":"ativo circulante / passivo circulante"},"comentario":{"resolucao":"CERTO. LC = Ativo Circulante ÷ Passivo Circulante; acima de 1, há mais direitos de curto prazo do que obrigações de curto prazo. O que salva o item é o \"em tese\", e é aí que mora a lição: o índice não distingue estoque encalhado de dinheiro em caixa, nem casa os PRAZOS — a duplicata pode vencer depois da obrigação que deveria pagar. Por isso liquidez corrente alta não é sinônimo de solvência, e por isso existe a liquidez seca, que expurga os estoques justamente para corrigir essa cegueira. Item que dissesse que LC > 1 \"assegura\" o pagamento estaria ERRADO.","fundamento":"Doutrina contábil — análise de índices financeiros (liquidez).","macete":"Liquidez corrente = AC / PC. Sempre ativo dividido por passivo, nunca o inverso.","erroComum":"Inverter a fórmula, dividindo o passivo circulante pelo ativo circulante.","comoBancaPensa":"Item de fixação sobre um dos índices financeiros mais cobrados em provas."}},"CT-026":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a fórmula correta do índice de liquidez corrente.","palavraCritica":"passivo circulante pelo ativo circulante"},"comentario":{"resolucao":"ERRADO. A fórmula correta do índice de liquidez corrente é Ativo Circulante / Passivo Circulante, e não o inverso. Ademais, se o cálculo fosse feito na forma invertida proposta pelo item, um resultado superior a 1 indicaria, na verdade, situação financeira desfavorável (mais obrigações do que recursos de curto prazo).","fundamento":"Doutrina contábil — análise de índices financeiros (liquidez).","macete":"Liquidez corrente = AC / PC. Nunca inverta a fórmula.","erroComum":"Inverter numerador e denominador, distorcendo completamente a interpretação do índice.","comoBancaPensa":"Inverte a fórmula de um índice clássico para testar a memorização correta do candidato."}},"CT-027":{"cognitivo":{"motivo":"Cobrar a distinção entre regime de competência (regra geral contábil) e regime de caixa.","palavraCritica":"regime de competência ... independentemente do efetivo recebimento ou pagamento"},"comentario":{"resolucao":"CERTO. Competência olha o fato gerador; caixa olha a movimentação do dinheiro. Venda a prazo fechada em dezembro e recebida em março é receita de DEZEMBRO. É essa separação que dá sentido a contas como despesa antecipada e receita a receber — elas existem para acomodar a distância entre o fato e o pagamento. Cuidado com a extensão indevida: o setor público brasileiro adota regime MISTO na execução orçamentária (Lei 4.320/1964, art. 35 — receita pelo caixa, despesa pela competência). O enunciado se salva ao delimitar \"contabilidade societária\".","fundamento":"Doutrina contábil — princípios de contabilidade (regime de competência).","macete":"Competência = regra geral. Reconhece pelo FATO, não pelo dinheiro entrando/saindo.","erroComum":"Achar que o regime de caixa é a regra geral da contabilidade societária.","comoBancaPensa":"Item de fixação sobre um dos princípios contábeis mais fundamentais."}},"CT-028":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o regime de competência (e não o de caixa) é a regra geral contábil.","palavraCritica":"regime de caixa ... regra geral"},"comentario":{"resolucao":"ERRADO. A regra geral da contabilidade societária brasileira é o regime de COMPETÊNCIA (e não o de caixa): receitas e despesas são reconhecidas no período em que ocorrem, independentemente do efetivo recebimento ou pagamento em dinheiro.","fundamento":"Doutrina contábil — princípios de contabilidade (regime de competência).","macete":"Regra geral = competência. Regime de caixa é exceção em contextos específicos.","erroComum":"Inverter os dois regimes, tratando o de caixa como a regra geral contábil.","comoBancaPensa":"Troca os dois regimes entre si, testando a memorização da regra geral correta."}},"CT-029":{"cognitivo":{"motivo":"Fixar o regime contábil misto adotado pela Lei 4.320.","palavraCritica":"efetivamente pagas"},"comentario":{"resolucao":"ERRADO. Pertencem ao exercício financeiro as receitas nele arrecadadas e as despesas nele LEGALMENTE EMPENHADAS. É o chamado regime misto: caixa para as receitas e competência para as despesas. Despesa empenhada e não paga ao fim do exercício é inscrita em restos a pagar.","fundamento":"Lei 4.320/1964, art. 35, I e II.","macete":"Arrecadadas e empenhadas — regime misto.","erroComum":"Vincular a despesa ao exercício pelo pagamento.","comoBancaPensa":"Acerta o inciso I e altera o inciso II, aproveitando a simetria da frase para induzir leitura apressada."}},"CT-030":{"cognitivo":{"motivo":"Distinguir empenho de liquidação nos estágios da despesa pública.","palavraCritica":"O empenho ... verificação do direito adquirido"},"comentario":{"resolucao":"ERRADO. A definição apresentada é a de LIQUIDAÇÃO da despesa. O empenho é o ato emanado de autoridade competente que cria para o Estado obrigação de pagamento pendente ou não de implemento de condição, e antecede a liquidação na ordem dos estágios.","fundamento":"Lei 4.320/1964, art. 58 (empenho) e art. 63 (liquidação).","macete":"Empenho cria a obrigação; liquidação verifica o direito.","erroComum":"Trocar as definições de empenho e liquidação.","comoBancaPensa":"Transcreve com fidelidade a definição de um instituto e a atribui ao instituto vizinho."}},"CT-031":{"cognitivo":{"motivo":"Delimitar a classificação econômica da receita orçamentária.","palavraCritica":"operações de crédito"},"comentario":{"resolucao":"ERRADO. As receitas provenientes de operações de crédito são receitas de CAPITAL, por resultarem da constituição de dívidas. As demais categorias listadas — tributária, de contribuições, patrimonial, agropecuária, industrial e de serviços — são efetivamente receitas correntes.","fundamento":"Lei 4.320/1964, art. 11, §§1º e 2º.","macete":"Constituiu dívida, é receita de capital.","erroComum":"Classificar empréstimo como receita corrente por ingressar no caixa.","comoBancaPensa":"Reproduz o rol legal e anexa um item da categoria vizinha."}},"CT-032":{"cognitivo":{"motivo":"Fixar qual estágio da despesa é pressuposto de sua realização.","palavraCritica":"liquidação"},"comentario":{"resolucao":"ERRADO. A vedação legal é à realização de despesa sem prévio EMPENHO. A liquidação é estágio posterior ao empenho, de modo que exigi-la previamente inverteria a sequência legal dos estágios da despesa pública.","fundamento":"Lei 4.320/1964, art. 60.","macete":"Sem empenho prévio não há despesa.","erroComum":"Trocar empenho por liquidação.","comoBancaPensa":"Em frase curta, a troca de uma única palavra é mais difícil de perceber do que em texto longo."}},"CT-033":{"cognitivo":{"motivo":"Fixar a definição de liquidação no lugar certo.","palavraCritica":"liquidação ... verificação"},"comentario":{"resolucao":"CERTO. O art. 63 da Lei 4.320/1964 define a liquidação exatamente como a verificação do direito adquirido pelo credor com base nos títulos e documentos comprobatórios, apurando origem, objeto, valor e a quem se deve pagar.","fundamento":"Lei 4.320/1964, art. 63; art. 58.","macete":"Liquidação confere o direito do credor.","erroComum":"Atribuir a definição ao empenho.","comoBancaPensa":"Traz o par correto depois de muitas questões com a troca."}},"CT-034":{"cognitivo":{"motivo":"Fixar a classificação econômica correta da operação de crédito.","palavraCritica":"constituição de dívidas"},"comentario":{"resolucao":"CERTO. O art. 11, §2º, da Lei 4.320/1964 classifica como receitas de capital as provenientes da constituição de dívidas, o que abrange as operações de crédito. Não são receitas correntes, apesar do ingresso financeiro.","fundamento":"Lei 4.320/1964, art. 11, §§1º e 2º.","macete":"Constituiu dívida = receita de capital.","erroComum":"Classificar como corrente pelo ingresso em caixa.","comoBancaPensa":"Classificação correta acompanhada do fundamento."}},"CT-035":{"cognitivo":{"motivo":"Separar dois conceitos do plano de contas que a banca troca sistematicamente.","palavraCritica":"função"},"comentario":{"resolucao":"ERRADO. O que se descreve é o FUNCIONAMENTO da conta — a mecânica de débito e crédito que faz o saldo subir ou descer. A FUNÇÃO é outra coisa: é a finalidade da conta, o que ela se destina a registrar. A conta Fornecedores tem por função registrar as obrigações com terceiros pelo fornecimento de bens e serviços; seu funcionamento é aumentar a crédito e diminuir a débito. Um responde 'para que serve', o outro 'como se movimenta'.","fundamento":"Doutrina contábil — estrutura do plano de contas (elenco, função, funcionamento e codificação).","macete":"Função = para que serve. Funcionamento = como debita e credita.","erroComum":"Tratar os dois termos como sinônimos por aparecerem juntos na definição do plano de contas.","comoBancaPensa":"Descreve corretamente um conceito e o rotula com o nome do outro."}},"CT-036":{"cognitivo":{"motivo":"Distinguir instrumento de organização interna de livro contábil obrigatório.","palavraCritica":"livros contábeis obrigatórios"},"comentario":{"resolucao":"ERRADO. O plano de contas não é livro contábil e não se sujeita a registro ou autenticação. É instrumento de organização interna da escrituração, elaborado por cada entidade conforme suas necessidades e seu ramo de atividade. Livro obrigatório por excelência é o Diário, exigido pela legislação comercial e fiscal; o Razão é auxiliar de escrituração. O plano de contas antecede os dois: é o mapa que define quais contas serão usadas e como.","fundamento":"Doutrina contábil — livros de escrituração; Lei 6.404/1976, art. 177.","macete":"Plano de contas organiza; Diário registra. Só o segundo é livro obrigatório.","erroComum":"Presumir formalidade de registro por se tratar de documento contábil estruturado.","comoBancaPensa":"Empresta ao plano de contas a formalidade que pertence aos livros de escrituração."}},"CT-037":{"cognitivo":{"motivo":"Cobrar os componentes do plano de contas além da simples relação de contas.","palavraCritica":"esgota-se"},"comentario":{"resolucao":"ERRADO. O elenco é apenas um dos componentes. O plano de contas compreende também a FUNÇÃO de cada conta (o que registra), o seu FUNCIONAMENTO (como é debitada e creditada) e a CODIFICAÇÃO que organiza a hierarquia entre contas sintéticas e analíticas. Um plano reduzido a lista de nomes não cumpriria seu papel, que é padronizar a escrituração e permitir que pessoas diferentes classifiquem o mesmo fato da mesma forma.","fundamento":"Doutrina contábil — estrutura e finalidade do plano de contas.","macete":"Elenco + função + funcionamento + codificação. O elenco sozinho não basta.","erroComum":"Reduzir o plano de contas à relação de contas disponíveis.","comoBancaPensa":"Apresenta parte verdadeira do conceito com verbo de exclusividade."}},"CT-038":{"cognitivo":{"motivo":"Fixar a distinção por nível de detalhamento, base da codificação do plano de contas.","palavraCritica":"não recebem lançamentos diretos"},"comentario":{"resolucao":"CERTO. A conta sintética é totalizadora: seu saldo resulta da soma das contas que ela agrupa, e por isso não recebe lançamento direto. A analítica é o último nível da hierarquia e é onde a escrituração efetivamente ocorre. Exemplo: 'Disponibilidades' é sintética; 'Caixa' e 'Banco Conta Movimento' são analíticas, e é nelas que se debita e credita. Confundir os níveis leva a lançar em conta totalizadora, o que quebra a estrutura do plano.","fundamento":"Doutrina contábil — classificação das contas quanto ao nível de detalhamento.","macete":"Sintética totaliza. Analítica recebe lançamento.","erroComum":"Inverter os papéis por associar 'analítica' a análise e não a detalhe.","comoBancaPensa":"Item conceitual correto, usado como âncora antes das inversões nos itens seguintes."}},"CT-039":{"cognitivo":{"motivo":"Fixar a característica que explica a presença de saldos de ambas as naturezas no ativo e no passivo.","palavraCritica":"inversa"},"comentario":{"resolucao":"CERTO. A conta redutora — ou retificadora — existe para diminuir o saldo do grupo a que pertence, e por isso tem natureza contrária. Depreciação Acumulada é CREDORA e fica dentro do Ativo Imobilizado, reduzindo-o; Ações em Tesouraria é DEVEDORA e fica no Patrimônio Líquido, reduzindo-o. É essa mecânica que faz o ativo conter contas credoras, e não apenas devedoras — desdobramento cobrado com frequência.","fundamento":"Doutrina contábil — contas retificadoras; Lei 6.404/1976, arts. 178 a 182.","macete":"Redutora tem sempre a natureza contrária à do grupo que retifica.","erroComum":"Supor que toda conta do ativo é devedora sem exceção.","comoBancaPensa":"Conceito simples que serve de premissa para itens mais difíceis sobre natureza de saldos."}},"CT-040":{"cognitivo":{"motivo":"Cobrar a consequência das contas redutoras sobre a composição dos grupos patrimoniais.","palavraCritica":"tanto ... quanto"},"comentario":{"resolucao":"CERTO, e a explicação está nas contas redutoras. A REGRA é que o ativo tenha saldo devedor e o passivo, credor; as retificadoras rompem essa uniformidade dentro de cada grupo. No ativo, Depreciação Acumulada e Provisão para Perdas de Crédito Esperadas são credoras. No passivo, Encargos Financeiros a Transcorrer é devedora, reduzindo a obrigação. Item que afirme uniformidade absoluta de natureza dentro do grupo estaria errado.","fundamento":"Doutrina contábil — natureza dos saldos e contas retificadoras; Lei 6.404/1976, art. 178.","macete":"A regra é uniforme; as redutoras são a exceção que a banca cobra.","erroComum":"Negar por aplicar a regra geral sem lembrar das retificadoras.","comoBancaPensa":"Afirma a exceção como se fosse descrição geral, punindo quem só decorou a regra."}},"CT-041":{"cognitivo":{"motivo":"Cobrar a natureza patrimonial de uma conta cujo nome sugere resultado.","palavraCritica":"lucros ou prejuízos acumulados"},"comentario":{"resolucao":"ERRADO. Lucros ou Prejuízos Acumulados é conta PATRIMONIAL, integrante do Patrimônio Líquido, e não conta de resultado. A distinção é de ciclo de vida: contas de resultado nascem e morrem dentro do exercício — são encerradas na apuração e não migram para o balanço; a de lucros acumulados é permanente e figura no balanço patrimonial. O nome engana porque contém a palavra 'lucros', mas ela RECEBE o resultado apurado, não o compõe.","fundamento":"Lei 6.404/1976, art. 178, § 2º, III, e art. 187; doutrina contábil — encerramento das contas de resultado.","macete":"Resultado zera no fim do exercício. Lucros acumulados fica no balanço.","erroComum":"Classificar pela palavra 'lucros' presente no nome da conta.","comoBancaPensa":"Anexa uma conta patrimonial a uma afirmação verdadeira sobre contas de resultado."}},"CT-042":{"cognitivo":{"motivo":"Fixar que o grupo de resultado não tem natureza única.","palavraCritica":"conforme se trate de despesa ou de receita"},"comentario":{"resolucao":"CERTO. Despesas são devedoras e receitas são credoras — o grupo de resultado, portanto, comporta as duas naturezas, e não uma só. A lógica está no efeito sobre o patrimônio líquido: a receita o aumenta, e aumento de PL registra-se a crédito; a despesa o reduz, e redução de PL registra-se a débito. Essa mesma lógica explica por que ativo é devedor e passivo é credor, e é o que permite deduzir a natureza de qualquer conta sem decorar.","fundamento":"Doutrina contábil — método das partidas dobradas e natureza dos saldos.","macete":"Aumenta PL, credita. Reduz PL, debita. Receita e despesa seguem daí.","erroComum":"Atribuir natureza única ao grupo de resultado, como se faz com ativo e passivo.","comoBancaPensa":"Cobra a dedução da natureza a partir do efeito patrimonial."}},"CT-043":{"cognitivo":{"motivo":"Cobrar que a segregação por prazo alcança apenas parte das contas.","palavraCritica":"Todas"},"comentario":{"resolucao":"ERRADO. A segregação entre circulante e não circulante é critério de PRAZO de realização ou exigibilidade, aplicável ao ativo e ao passivo. Não alcança as contas de resultado — não existe 'receita circulante' —, nem o patrimônio líquido, nem as contas de compensação. Item que estende a classificação a todo o plano de contas generaliza um critério que a própria estrutura do balanço restringe a dois grupos.","fundamento":"Lei 6.404/1976, art. 178, §§ 1º e 2º.","macete":"Circulante/não circulante é só para ativo e passivo. Resultado e PL ficam fora.","erroComum":"Estender ao plano inteiro um critério próprio dos grupos patrimoniais.","comoBancaPensa":"Aplica a todo o universo um critério verdadeiro apenas para um subconjunto."}},"CT-044":{"cognitivo":{"motivo":"Fixar a função das contas de compensação e sua ligação com atos administrativos.","palavraCritica":"atos administrativos"},"comentario":{"resolucao":"CERTO. As contas de compensação são o registro dos ATOS administrativos — aqueles que, por si, não modificam o patrimônio, mas podem vir a modificá-lo. Aval concedido, garantia prestada, contrato de seguro firmado: nada disso altera ativo, passivo ou PL no momento em que ocorre, mas todos criam risco potencial que interessa ao usuário da informação. É a distinção clássica entre ATO e FATO administrativo: o fato altera o patrimônio, o ato não altera mas pode vir a alterar.","fundamento":"Doutrina contábil — atos e fatos administrativos; contas de compensação.","macete":"Ato pode vir a mexer no patrimônio; fato já mexeu. Compensação registra o ato.","erroComum":"Confundir contas de compensação com contas retificadoras.","comoBancaPensa":"Cobra a ponte entre a teoria dos atos administrativos e a estrutura de contas."}},"CT-045":{"cognitivo":{"motivo":"Cobrar a direção correta do lançamento em fato permutativo, com justificativa enganosa.","palavraCritica":"há saída de dinheiro e entrada de um bem"},"comentario":{"resolucao":"ERRADO. O lançamento está invertido: debita-se IMÓVEIS e credita-se BANCOS. A justificativa oferecida pelo item é verdadeira nos fatos — dinheiro sai, bem entra — mas conduz à conclusão contrária, porque no ativo o aumento se registra a DÉBITO e a redução a CRÉDITO. Imóveis aumentou, logo é debitada; Bancos diminuiu, logo é creditada. Trata-se de fato permutativo: troca-se um elemento do ativo por outro, sem alterar o patrimônio líquido.","fundamento":"Doutrina contábil — método das partidas dobradas; fatos permutativos.","macete":"No ativo: aumentou, debita. Diminuiu, credita.","erroComum":"Associar 'saída de dinheiro' a débito por analogia com o extrato bancário.","comoBancaPensa":"Oferece uma descrição factual correta que empurra o candidato para o lançamento invertido."}},"CT-046":{"cognitivo":{"motivo":"Fixar que pagamento antecipado gera ativo, não despesa imediata.","palavraCritica":"no ativo"},"comentario":{"resolucao":"CERTO. No momento do pagamento não há despesa, e sim um DIREITO: a entidade pagou e passará a receber o benefício ao longo do tempo. Por isso o registro inicial é no ativo, e a apropriação ao resultado acompanha a fluência do prazo — é aplicação direta do regime de competência. A contrapartida existe do outro lado: valor recebido antecipadamente por serviço ainda não prestado é PASSIVO (receita antecipada), porque gera obrigação de entregar. Pagou adiantado, ativo; recebeu adiantado, passivo.","fundamento":"Doutrina contábil — regime de competência; Lei 6.404/1976, art. 179, I.","macete":"Pagou antes: ativo. Recebeu antes: passivo.","erroComum":"Reconhecer despesa integral no desembolso, seguindo o regime de caixa.","comoBancaPensa":"Testa a aplicação do regime de competência num caso concreto de fluxo antecipado."}},"CT-047":{"cognitivo":{"motivo":"Cobrar a natureza de passivo do adiantamento recebido.","palavraCritica":"por já estar disponível em caixa"},"comentario":{"resolucao":"ERRADO. Receber dinheiro não é ganhar receita. Enquanto o serviço não é prestado, a entidade tem OBRIGAÇÃO de entregá-lo — o registro é no passivo, como receita antecipada ou adiantamento de clientes, e só migra para o resultado quando a prestação ocorrer. A justificativa do item, de que o valor já está em caixa, é exatamente o raciocínio do regime de caixa, que não é o adotado pela contabilidade societária. Note a simetria com as despesas antecipadas, que são ativo pela razão inversa.","fundamento":"Doutrina contábil — regime de competência; CPC 47 (reconhecimento de receita).","macete":"Recebeu sem entregar: passivo, não receita.","erroComum":"Reconhecer receita pela disponibilidade financeira.","comoBancaPensa":"Usa a existência do dinheiro em caixa como justificativa aparentemente irrefutável."}},"CT-048":{"cognitivo":{"motivo":"Separar a igualdade de valores da quantidade de contas envolvidas.","palavraCritica":"uma única"},"comentario":{"resolucao":"ERRADO. O método exige igualdade entre a soma dos débitos e a soma dos créditos, não que haja uma conta de cada lado. Lançamentos de segunda, terceira e quarta fórmulas envolvem várias contas: uma compra parte à vista e parte a prazo debita Mercadorias e credita Caixa E Fornecedores, e continua obedecendo às partidas dobradas. O item confunde a regra de equivalência de VALORES com uma inexistente regra de QUANTIDADE de contas.","fundamento":"Doutrina contábil — método das partidas dobradas; fórmulas de lançamento.","macete":"O que tem de bater é o valor, não o número de contas.","erroComum":"Generalizar a primeira fórmula de lançamento como se fosse a única.","comoBancaPensa":"Converte o caso mais simples em regra geral obrigatória."}},"CT-049":{"cognitivo":{"motivo":"Cobrar a inversão entre as definições dos dois regimes.","palavraCritica":"regime de caixa"},"comentario":{"resolucao":"ERRADO. A definição apresentada é a do regime de COMPETÊNCIA, e o item a rotula como regime de caixa. O de caixa faz o oposto: reconhece receitas e despesas apenas quando há efetivo recebimento ou pagamento, ignorando o momento do fato gerador. A pista está na própria frase — 'independentemente da movimentação financeira' é incompatível com um regime que se chama, justamente, de caixa. Contradição interna é o sinal a procurar.","fundamento":"Doutrina contábil — regimes de escrituração; CPC 00 (Estrutura Conceitual).","macete":"Caixa olha o dinheiro. Competência olha o fato gerador.","erroComum":"Validar a definição por ela ser correta — só que do outro regime.","comoBancaPensa":"Troca o rótulo mantendo o conteúdo íntegro: troca-conceito na forma mais pura."}},"CT-050":{"cognitivo":{"motivo":"Cobrar a inversão do critério de reconhecimento da receita.","palavraCritica":"somente no momento do recebimento"},"comentario":{"resolucao":"ERRADO — o item inverte os dois lados. Pelo regime de competência a receita é reconhecida quando a entidade cumpre sua obrigação de desempenho, tipicamente na entrega do produto ou na prestação do serviço, e não quando recebe. Uma venda a prazo em dezembro é receita de dezembro, ainda que o dinheiro entre em março. O critério condicionado ao recebimento é o do regime de caixa, e a menção à irrelevância da entrega é o oposto exato do que a norma exige.","fundamento":"Doutrina contábil — regime de competência; CPC 47, obrigação de desempenho.","macete":"Competência: entregou, é receita. Recebeu ou não, é outra conversa.","erroComum":"Ler 'competência' e associar ao momento em que o dinheiro se torna disponível.","comoBancaPensa":"Aplica ao regime nomeado o critério do regime oposto."}},"CT-051":{"cognitivo":{"motivo":"Fixar o critério de reconhecimento da despesa, simétrico ao da receita.","palavraCritica":"independentemente do respectivo fluxo de caixa"},"comentario":{"resolucao":"CERTO. A despesa pertence ao período em que é incorrida, isto é, em que o bem foi consumido ou o serviço utilizado, e não ao período do pagamento. A energia elétrica consumida em dezembro e paga em janeiro é despesa de dezembro. É a mesma lógica aplicada à receita, e é ela que dá sentido às contas de provisão e de valores a pagar: elas existem justamente para acomodar a distância entre o fato e o desembolso.","fundamento":"Doutrina contábil — regime de competência; CPC 00 (Estrutura Conceitual).","macete":"Incorreu, é despesa. Pagar é evento financeiro, não contábil.","erroComum":"Condicionar o reconhecimento da despesa ao desembolso.","comoBancaPensa":"Item literal correto, âncora para as inversões cobradas nos itens vizinhos."}},"CT-052":{"cognitivo":{"motivo":"Exigir a aplicação numérica do regime, distinguindo dos valores de caixa.","palavraCritica":"pelo regime de competência"},"comentario":{"resolucao":"CERTO. Pelo regime de competência interessam a receita ganha e a despesa incorrida, não o que transitou pelo caixa: 240.000 − 186.000 = 54.000 de lucro. Os valores recebidos e pagos são distratores — pelo regime de CAIXA o resultado seria 205.000 − 178.000 = 27.000, e é esse número que a banca costuma oferecer como se fosse o da competência. Repare que a diferença entre os dois resultados (27.000) corresponde exatamente ao que ficou a receber menos o que ficou a pagar: 35.000 − 8.000.","fundamento":"Doutrina contábil — regime de competência x regime de caixa na apuração do resultado.","macete":"Competência usa vendeu e incorreu. Caixa usa recebeu e pagou.","erroComum":"Calcular com os valores efetivamente movimentados no caixa.","comoBancaPensa":"Fornece os quatro números para que o candidato escolha o par errado."}},"CT-053":{"cognitivo":{"motivo":"Exigir o cálculo pelo regime de caixa, invertendo o par de valores relevantes.","palavraCritica":"regime de caixa"},"comentario":{"resolucao":"CERTO. Pelo regime de caixa contam apenas os valores efetivamente movimentados: 62.000 recebidos − 65.000 pagos = −3.000, ou seja, prejuízo de 3.000. Pelo regime de competência o quadro se inverte: 90.000 − 71.000 = 19.000 de lucro. O caso mostra por que o regime importa — a mesma entidade, no mesmo período, apresenta prejuízo por um critério e lucro pelo outro, e é essa divergência que justifica a competência ser a regra societária.","fundamento":"Doutrina contábil — regime de caixa x regime de competência.","macete":"Caixa é só o que entrou menos o que saiu.","erroComum":"Aplicar os valores de competência ao regime de caixa.","comoBancaPensa":"Inverte o comando em relação ao item anterior, cobrando atenção ao regime pedido."}},"CT-054":{"cognitivo":{"motivo":"Cobrar a universalidade do regime de competência na escrituração contábil.","palavraCritica":"somente"},"comentario":{"resolucao":"ERRADO. A competência é o regime da escrituração contábil de todas as entidades, independentemente do porte — inclusive as pequenas e médias, cuja norma específica é construída sobre ele. O que varia com o porte é o conjunto de demonstrações exigidas e o nível de divulgação, não o regime de reconhecimento. Não confundir com regimes de apuração TRIBUTÁRIA: ali existem opções, como o lucro presumido, mas isso é matéria fiscal, distinta da escrituração contábil.","fundamento":"Lei 6.404/1976, art. 177; CPC PME; doutrina contábil — regime de competência.","macete":"Competência vale para todas. Porte muda divulgação, não regime.","erroComum":"Transportar para a contabilidade as opções existentes na apuração tributária.","comoBancaPensa":"Cria uma faculdade por porte, apoiada na existência real de regimes fiscais opcionais."}},"CT-055":{"cognitivo":{"motivo":"Fixar a razão de ser da competência como regime da contabilidade societária.","palavraCritica":"desempenho econômico"},"comentario":{"resolucao":"CERTO. É a justificativa da Estrutura Conceitual para a competência ser a regra: ao reconhecer os efeitos das transações quando ocorrem, e não quando o dinheiro se movimenta, ela informa melhor sobre o desempenho ECONÔMICO da entidade. O regime de caixa informa sobre o desempenho FINANCEIRO — igualmente relevante, e por isso a Demonstração dos Fluxos de Caixa existe e é obrigatória. Não são regimes concorrentes: um mede geração de riqueza, o outro, geração de liquidez.","fundamento":"CPC 00 (Estrutura Conceitual); Lei 6.404/1976, art. 176.","macete":"Competência mede riqueza. Caixa mede liquidez. A DFC existe para o segundo.","erroComum":"Tratar o regime de caixa como irrelevante para a contabilidade.","comoBancaPensa":"Cobra a fundamentação conceitual, e não apenas a definição operacional."}},"CT-056":{"cognitivo":{"motivo":"Fixar o art. 35 da Lei 4.320, que combina os dois regimes em um único dispositivo.","palavraCritica":"regime misto"},"comentario":{"resolucao":"CERTO. É o art. 35 da Lei 4.320/1964: receita pelo regime de CAIXA (arrecadação) e despesa pelo regime de COMPETÊNCIA (empenho). A combinação é o que a doutrina chama de regime misto, e vale para a execução ORÇAMENTÁRIA. Atenção ao recorte, porque é onde a banca ataca: a contabilidade PATRIMONIAL do setor público segue a competência integral, conforme as normas aplicadas ao setor público. Item que estenda o regime misto à contabilidade patrimonial estaria errado.","fundamento":"Lei 4.320/1964, art. 35; NBC TSP — Estrutura Conceitual.","macete":"Receita arrecadada, despesa empenhada. Misto, e só na execução orçamentária.","erroComum":"Inverter os regimes ou estender o misto à contabilidade patrimonial pública.","comoBancaPensa":"Cobra o único dispositivo brasileiro que combina os dois regimes por lei."}},"CT-057":{"cognitivo":{"motivo":"Cobrar a inversão dos critérios do art. 35, com uso de termo tecnicamente impossível.","palavraCritica":"receitas ... empenhadas"},"comentario":{"resolucao":"ERRADO, e o erro é duplo. Primeiro, os critérios estão trocados: a lei vincula a receita à ARRECADAÇÃO e a despesa ao EMPENHO, não o contrário. Segundo, 'receita empenhada' é impossibilidade técnica — empenho é estágio da DESPESA, jamais da receita. Reconhecer essa incompatibilidade de vocabulário permite eliminar o item sem sequer lembrar do art. 35: nenhum dispositivo poderia falar em empenhar receita.","fundamento":"Lei 4.320/1964, arts. 35, 58 e 60.","macete":"Empenho é estágio de despesa. Receita não se empenha.","erroComum":"Aceitar a inversão por reconhecer os dois termos como do vocabulário da lei.","comoBancaPensa":"Embaralha termos verdadeiros do mesmo diploma, criando combinação impossível."}},"CT-058":{"cognitivo":{"motivo":"Cobrar que a forma do recebimento é irrelevante para o reconhecimento por competência.","palavraCritica":"depende"},"comentario":{"resolucao":"ERRADO. No regime de competência o recebimento é irrelevante para o reconhecimento — tanto a existência quanto a forma. Reconhece-se a receita quando a entidade cumpre a obrigação de desempenho, ainda que nada tenha entrado e ainda que a contraprestação venha a ser recebida em bens, títulos ou serviços. O item cria uma condição de forma que nem o regime de caixa impõe, já que este se satisfaz com qualquer ingresso.","fundamento":"Doutrina contábil — regime de competência; CPC 47.","macete":"Competência não pergunta se recebeu, muito menos como.","erroComum":"Confundir reconhecimento contábil com liquidação financeira.","comoBancaPensa":"Adiciona um requisito de forma sobre um critério que já dispensa o próprio recebimento."}},"CT-059":{"cognitivo":{"motivo":"Fixar a base legal da escrituração e o princípio da uniformidade.","palavraCritica":"uniformes no tempo"},"comentario":{"resolucao":"CERTO. É o art. 177 da Lei 6.404/1976. A uniformidade no tempo é o que torna as demonstrações comparáveis entre exercícios — mudar de critério a cada ano permitiria maquiar tendências. Isso não significa imutabilidade: a alteração é possível, mas exige divulgação em nota explicativa dos efeitos sobre o resultado. O mesmo artigo é a âncora legal da competência na escrituração societária.","fundamento":"Lei 6.404/1976, art. 177, caput.","macete":"Uniformidade permite comparar exercícios. Mudou, tem de explicar em nota.","erroComum":"Ler uniformidade como proibição absoluta de mudar de critério.","comoBancaPensa":"Transcreve dispositivo longo, apostando que a extensão iniba a conferência."}},"CT-060":{"cognitivo":{"motivo":"Cobrar a distinção entre pagamento do principal e pagamento de juros.","palavraCritica":"juros"},"comentario":{"resolucao":"ERRADO. Pagar JUROS é despesa: reduz o ativo sem reduzir obrigação equivalente, e portanto diminui o patrimônio líquido — fato modificativo diminutivo. O raciocínio do item vale para o pagamento do PRINCIPAL, esse sim permutativo, porque a saída de caixa é compensada pela baixa da dívida. A mesma operação bancária comporta os dois fatos, e a banca aproveita a proximidade para trocar um pelo outro.","fundamento":"Doutrina contábil — classificação dos fatos administrativos.","macete":"Principal: permutativo. Juros: modificativo diminutivo.","erroComum":"Tratar toda saída de caixa vinculada a empréstimo como permutativa.","comoBancaPensa":"Aplica a um componente da operação a classificação que só vale para o outro."}},"CT-061":{"cognitivo":{"motivo":"Fixar o conceito de fato misto a partir de operação corriqueira.","palavraCritica":"fato misto"},"comentario":{"resolucao":"CERTO. A operação tem duas naturezas simultâneas: a baixa da duplicata contra a entrada em caixa é permuta dentro do ativo; o desconto concedido é despesa, que reduz o patrimônio líquido. Reunidas no mesmo fato, caracterizam o fato misto — também chamado composto. Ele é diminutivo quando envolve despesa, como aqui, e aumentativo quando envolve receita, caso do recebimento com juros por atraso.","fundamento":"Doutrina contábil — fatos mistos ou compostos.","macete":"Misto = permuta + variação de PL na mesma operação.","erroComum":"Classificar só pela parte mais visível da operação.","comoBancaPensa":"Usa operação rotineira que a maioria classifica pela metade."}},"CT-062":{"cognitivo":{"motivo":"Separar ato de fato administrativo e localizar o registro correto.","palavraCritica":"fato administrativo modificativo"},"comentario":{"resolucao":"ERRADO. Trata-se de ATO administrativo relevante, não de fato: nada no patrimônio se altera no momento da assinatura da fiança, embora exista risco de vir a alterar. Por isso o registro se dá em contas de COMPENSAÇÃO, e não em conta de resultado — não há despesa a reconhecer enquanto a garantia não for executada. Se e quando for, aí sim nasce o fato administrativo, com efeito real sobre o patrimônio.","fundamento":"Doutrina contábil — atos e fatos administrativos; contas de compensação.","macete":"Ato: nada mudou ainda, vai para compensação. Fato: mudou, vai para o balanço.","erroComum":"Reconhecer despesa no momento em que a garantia é prestada.","comoBancaPensa":"Trata como fato aquilo que a doutrina classifica como ato, e desloca o registro."}},"CT-063":{"cognitivo":{"motivo":"Cobrar quais erros o balancete NÃO detecta, ponto central da sua utilidade real.","palavraCritica":"assegura"},"comentario":{"resolucao":"ERRADO. O balancete comprova apenas a igualdade aritmética entre débitos e créditos. Passam por ele intactos: o lançamento feito em conta errada mas de mesma natureza, o fato inteiramente omitido, o lançamento duplicado e a inversão entre a conta debitada e a creditada quando os valores coincidem. Em todos esses casos os totais batem e a escrituração está errada. Por isso o balancete é instrumento de VERIFICAÇÃO, não de validação.","fundamento":"Doutrina contábil — balancete de verificação e limites de detecção de erros.","macete":"Bater não é estar certo. Conta trocada e fato omitido não desequilibram nada.","erroComum":"Tratar o equilíbrio aritmético como atestado de correção da escrituração.","comoBancaPensa":"Eleva um instrumento de conferência parcial à condição de garantia integral."}},"CT-064":{"cognitivo":{"motivo":"Cobrar que o balancete abrange todas as contas com saldo, inclusive as de resultado.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"ERRADO. O balancete relaciona TODAS as contas com saldo na data, patrimoniais e de resultado. As contas de resultado acumulam movimento ao longo do exercício e por isso aparecem — o que ocorre ao final não é a apuração de seus saldos, e sim o ENCERRAMENTO, quando são zeradas contra a conta de apuração do resultado. Confundir acumular saldo com apurar resultado é a raiz do erro.","fundamento":"Doutrina contábil — balancete de verificação; encerramento das contas de resultado.","macete":"Balancete mostra tudo que tem saldo. Encerramento é que zera o resultado.","erroComum":"Supor que contas de resultado só existem no encerramento.","comoBancaPensa":"Usa uma verdade sobre o encerramento para restringir indevidamente o balancete."}},"CT-065":{"cognitivo":{"motivo":"Fixar que permutativo se define pela ausência de efeito no PL, não pela ausência de variação nos grupos.","palavraCritica":"ainda que aumente"},"comentario":{"resolucao":"CERTO. Permutativo não significa que nada muda de tamanho — significa que o PATRIMÔNIO LÍQUIDO não se altera. Aqui o ativo cresce pelo veículo e o passivo cresce pela obrigação, na mesma medida, e o PL permanece intacto. Esse tipo é chamado de permutativo aumentativo, ou quantitativo-qualitativo. Item que exija que o total do ativo permaneça inalterado para haver permuta estaria errado.","fundamento":"Doutrina contábil — classificação dos fatos administrativos.","macete":"Permutativo é o que não mexe no PL, mesmo aumentando ativo e passivo.","erroComum":"Exigir que o total do balanço permaneça constante.","comoBancaPensa":"Contraexemplo: o item afirma o que o candidato tenderia a negar por reflexo."}},"CT-066":{"cognitivo":{"motivo":"Contraexemplo: aqui a afirmação categórica é verdadeira e deve ser marcada CERTO.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"CERTO — e o termo categórico procede. Caixa registra dinheiro em espécie sob guarda da entidade, e não há como entregar numerário que não se tem; saldo credor em caixa é impossibilidade material, sinalizando lançamento omitido, invertido ou registrado em conta errada. Não confundir com BANCOS, onde o saldo credor é perfeitamente possível e significa conta garantida ou cheque especial utilizado — ali a instituição adiantou recursos, e o saldo credor representa dívida real.","fundamento":"Doutrina contábil — natureza das contas do disponível.","macete":"Caixa credor: erro. Bancos credor: cheque especial, e é dívida.","erroComum":"Marcar ERRADO por reflexo diante de 'necessariamente'.","comoBancaPensa":"Usa termo absoluto verdadeiro para punir quem eliminou o item sem pensar."}},"CT-067":{"cognitivo":{"motivo":"Cobrar a diferença entre disponibilidade em espécie e conta bancária com limite.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"ERRADO. Bancos admite saldo credor sem erro algum: significa que a entidade utilizou limite de conta garantida ou cheque especial, e o saldo credor expressa uma obrigação real perante a instituição financeira, devendo ser reclassificado para o passivo circulante na apresentação do balanço. A analogia com caixa não se sustenta, porque ali o saldo credor é materialmente impossível. Mesmo grupo, comportamentos diferentes.","fundamento":"Doutrina contábil — disponibilidades; Lei 6.404/1976, art. 178, § 1º.","macete":"Bancos pode ficar credor — vira passivo, não erro.","erroComum":"Estender a impossibilidade do caixa a todas as disponibilidades.","comoBancaPensa":"Constrói a generalização a partir de um item anterior verdadeiro, criando armadilha em par."}},"CT-068":{"cognitivo":{"motivo":"Ligar um instituto patrimonial ao regime que o justifica.","palavraCritica":"desembolso ocorreu integralmente em um único momento"},"comentario":{"resolucao":"CERTO. A depreciação é a expressão mais visível da competência: a entidade paga o bem de uma vez, mas o consome ao longo de anos, e a despesa deve aparecer nos exercícios em que o benefício é fruído — não naquele em que o dinheiro saiu. Sob regime de caixa a máquina inteira viraria despesa no ano da compra, distorcendo o resultado daquele exercício e dos seguintes. Vale notar que a depreciação não gera saída de caixa; é despesa sem desembolso, e por isso é somada de volta na Demonstração dos Fluxos de Caixa pelo método indireto.","fundamento":"Lei 6.404/1976, art. 183, § 2º; CPC 27; doutrina contábil — regime de competência.","macete":"Pagou uma vez, consome por anos — a competência distribui.","erroComum":"Ver a depreciação como ajuste fiscal em vez de aplicação do regime.","comoBancaPensa":"Cobra a conexão entre um instituto concreto e o princípio que o fundamenta."}},"CT-069":{"cognitivo":{"motivo":"Cobrar a localização da provisão retificadora, que o nome sugere ser passivo.","palavraCritica":"passivo circulante"},"comentario":{"resolucao":"ERRADO. É conta RETIFICADORA DO ATIVO, credora, apresentada como redução das Contas a Receber — ajusta o valor do direito ao montante que se espera efetivamente realizar. Não há obrigação da entidade perante ninguém: quem deve é o cliente, e o risco é de não receber, não de ter de pagar. A palavra 'provisão' induz ao erro por lembrar as provisões do passivo, como a de férias e a para contingências, essas sim obrigações.","fundamento":"Lei 6.404/1976, art. 183, I; CPC 48; doutrina contábil — contas retificadoras.","macete":"Provisão para perdas com recebíveis retifica ATIVO. Provisão de férias é passivo.","erroComum":"Classificar pela palavra 'provisão', sem perguntar quem deve a quem.","comoBancaPensa":"Explora um termo que aparece nos dois lados do balanço com naturezas opostas."}},"CT-070":{"cognitivo":{"motivo":"Aplicar concretamente os limites de detecção do balancete.","palavraCritica":"desequilíbrio"},"comentario":{"resolucao":"ERRADO. O valor foi debitado e creditado corretamente, apenas na conta errada — e como ambas são despesas, de mesma natureza devedora, as somas continuam iguais. O balancete fecha e o erro permanece invisível ali. A distorção existe e é real: o resultado total está certo, mas a composição das despesas está errada, o que compromete a análise por natureza de gasto. Erros dessa espécie só aparecem na conciliação de cada conta com seus documentos de suporte.","fundamento":"Doutrina contábil — balancete de verificação; erros não detectáveis pela igualdade aritmética.","macete":"Conta errada de mesma natureza: balancete fecha e o erro passa.","erroComum":"Supor que todo erro de escrituração desequilibra o balancete.","comoBancaPensa":"Cobra em caso concreto o limite teórico que o item anterior enuncia em abstrato."}},"CT-071":{"cognitivo":{"motivo":"Cobrar que a lei fixa a duração do exercício, não sua data de encerramento.","palavraCritica":"obrigatoriamente"},"comentario":{"resolucao":"ERRADO. A Lei 6.404/1976 fixa que o exercício social tem DURAÇÃO de um ano e que a data do término será estabelecida no estatuto — não impõe coincidência com o ano civil. Muitas companhias encerram em 30 de junho ou em 31 de março, e nada disso afeta a aplicação do regime de competência, que independe do calendário adotado. A exceção legal é a constituição da companhia ou a alteração estatutária, quando o exercício pode ter duração diversa.","fundamento":"Lei 6.404/1976, art. 175, caput e parágrafo único.","macete":"A lei fixa a duração (um ano), não a data de encerramento.","erroComum":"Confundir exercício social com ano-calendário fiscal.","comoBancaPensa":"Cria obrigatoriedade de data onde a lei delega ao estatuto."}},"CT-072":{"cognitivo":{"motivo":"Fixar o ciclo de vida das contas de resultado, que distingue transitórias de permanentes.","palavraCritica":"saldo zero"},"comentario":{"resolucao":"CERTO. Contas de resultado são TRANSITÓRIAS: medem desempenho de um período determinado e, cumprida essa função, são zeradas contra a apuração do resultado do exercício. O saldo apurado migra então para o Patrimônio Líquido. As patrimoniais, ao contrário, são PERMANENTES — o saldo de Caixa em 31 de dezembro é exatamente o saldo inicial de 1º de janeiro. É essa diferença que explica por que Lucros Acumulados não é conta de resultado, embora receba o resultado.","fundamento":"Doutrina contábil — encerramento do exercício; Lei 6.404/1976, art. 187.","macete":"Resultado é transitória e zera. Patrimonial é permanente e continua.","erroComum":"Supor que o saldo das contas de resultado é transportado para o exercício seguinte.","comoBancaPensa":"Cobra o mecanismo que fundamenta a classificação cobrada em outros itens."}},"CT-073":{"cognitivo":{"motivo":"Cobrar a vedação de rasura e o procedimento correto de retificação.","palavraCritica":"rasura"},"comentario":{"resolucao":"ERRADO. A escrituração não admite rasura, emenda ou entrelinha — o registro é feito em ordem cronológica e não pode ser apagado. A correção se faz por ESTORNO, com lançamento de igual valor e sentido inverso ao equivocado, seguido do lançamento correto; alternativamente, por transferência ou complementação, conforme o caso. O rastro do erro e da correção permanece visível, e é justamente isso que dá confiabilidade à escrituração.","fundamento":"Lei 6.404/1976, art. 177; NBC ITG 2000 — escrituração contábil.","macete":"Não se rasura escrituração: estorna-se.","erroComum":"Admitir correção por rasura visada, como em documentos administrativos comuns.","comoBancaPensa":"Importa da praxe administrativa um procedimento que a norma contábil veda."}},"CT-074":{"cognitivo":{"motivo":"Separar o regime da execução orçamentária do da contabilidade patrimonial pública.","palavraCritica":"contabilidade patrimonial"},"comentario":{"resolucao":"ERRADO. O regime misto do art. 35 da Lei 4.320/1964 rege a EXECUÇÃO ORÇAMENTÁRIA. A contabilidade PATRIMONIAL do setor público segue o regime de competência integral, reconhecendo as variações patrimoniais quando ocorrem os fatos geradores, independentemente da arrecadação ou do pagamento. As duas dimensões convivem no mesmo ente e por isso a informação contábil pública é apresentada em subsistemas distintos — orçamentário e patrimonial —, cada um com seu critério.","fundamento":"Lei 4.320/1964, art. 35; NBC TSP — Estrutura Conceitual; MCASP.","macete":"Orçamentário: misto. Patrimonial: competência integral.","erroComum":"Estender o art. 35 a toda a contabilidade do setor público.","comoBancaPensa":"Generaliza para o sistema inteiro uma regra que vale para um de seus subsistemas."}},"CT-075":{"cognitivo":{"motivo":"Testar se o candidato marca ERRADO só por ver 'único', mesmo quando a restrição é a da própria lei.","palavraCritica":"único"},"comentario":{"resolucao":"CERTO. O art. 1.180 do Código Civil é expresso: além dos demais livros exigidos por lei, é indispensável o Diário, que pode ser substituído por fichas no caso de escrituração mecanizada ou eletrônica. A palavra 'indispensável' aparece no texto legal referida a um único livro. O Razão é auxiliar e o Caixa deixa de ser exigido quando a entidade escritura o Diário com individuação. Note que a ressalva do enunciado — 'ressalvadas as exigências específicas previstas em leis especiais' — reproduz exatamente o 'além dos demais livros exigidos por lei' do dispositivo, e é ela que torna a restrição legítima.","fundamento":"Código Civil, arts. 1.180 e 1.181; Lei 6.404/1976, art. 177.","macete":"Diário: indispensável por lei. Razão: auxiliar. Plano de contas: nem livro é.","erroComum":"Marcar ERRADO por reflexo diante de 'único', sem checar se a exclusividade é a da lei.","comoBancaPensa":"Usa o formato restritivo que costuma sinalizar erro para punir quem responde sem ler o conteúdo."}},"CT-076":{"cognitivo":{"motivo":"Fixar o alcance da depreciação e separá-la de amortização e exaustão.","palavraCritica":"somente"},"comentario":{"resolucao":"CERTO. Depreciação é a alocação sistemática do valor depreciável de um bem tangível do imobilizado ao longo de sua vida útil. Terreno tem vida útil indefinida e por isso não se deprecia — ainda que a edificação construída sobre ele se deprecie normalmente. Bens intangíveis com vida útil definida sofrem AMORTIZAÇÃO, não depreciação; recursos naturais esgotáveis sofrem EXAUSTÃO. As três figuras são espécies do mesmo gênero, e a banca troca uma pela outra com frequência.","fundamento":"CPC 27 (Ativo Imobilizado); Lei 6.404/1976, art. 183, § 2º.","macete":"Tangível deprecia, intangível amortiza, recurso natural exaure. Terreno, nada.","erroComum":"Rejeitar o 'somente' sem perceber que o recorte descrito é exatamente o da norma.","comoBancaPensa":"Enuncia corretamente um limite técnico com a palavra que o candidato associa a erro."}},"CT-077":{"cognitivo":{"motivo":"Cobrar as formalidades intrínsecas literalmente exigidas pelo Código Civil.","palavraCritica":"vedados"},"comentario":{"resolucao":"CERTO. O enunciado reproduz o art. 1.183 do Código Civil quase palavra por palavra. Todas as exigências listadas — idioma e moeda nacionais, forma contábil, ordem cronológica de dia, mês e ano, e a vedação a espaços em branco, entrelinhas, borrões, rasuras, emendas e transportes para as margens — são as chamadas formalidades INTRÍNSECAS da escrituração. É por causa dessa vedação que a correção de erro se faz por estorno, transferência ou complementação, e nunca por rasura.","fundamento":"Código Civil, art. 1.183; ITG 2000 (R1).","macete":"Formalidade extrínseca é o livro por fora (termos, autenticação); intrínseca é o registro por dentro.","erroComum":"Supor que a lista é longa demais para ser toda legal e marcar ERRADO por excesso.","comoBancaPensa":"Acumula exigências verdadeiras até o enunciado 'parecer' inventado."}},"CT-078":{"cognitivo":{"motivo":"Cobrar a exigência de dupla assinatura e de transcrição das demonstrações no Diário.","palavraCritica":"devem ser lançados no livro Diário"},"comentario":{"resolucao":"CERTO. É o § 2º do art. 1.184 do Código Civil. O Diário não recebe apenas os lançamentos diários com individuação e clareza: ao fim do exercício, o balanço patrimonial e o balanço de resultado econômico são nele transcritos, com dupla assinatura — do contabilista habilitado e do empresário ou da sociedade. A dupla assinatura reparte a responsabilidade: técnica de um lado, de gestão do outro. Quem estuda apenas o conteúdo das demonstrações e ignora sua formalização de registro erra este item.","fundamento":"Código Civil, art. 1.184, §§ 1º e 2º.","macete":"Diário fecha o exercício: recebe o balanço e exige duas assinaturas.","erroComum":"Tratar a transcrição no Diário como praxe facultativa e não como exigência legal.","comoBancaPensa":"Explora a lacuna entre saber montar a demonstração e saber onde ela é formalizada."}}});
